    // loop and printf each
    return 0;
}

exercises.solution:
#include <stdio.h>
#include <stddef.h>

int main(void) {
    int nums[] = {10, 20, 30};
    for (size_t i = 0; i < 3; i++) printf("%d\n", nums[i]);
    return 0;
}

